module divide_by_4 (
    input clk,
    input reset,
    input enable,
    output reg out
);

reg [1:0] count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 2'b00;
        out <= 1'b0;
    end else if (enable) begin
        count <= count + 1;
        if (count == 2'b11) begin
            out <= ~out;
        end
    end
end

endmodule

