module zero_crossing_detector (
    input wire clk,
    input wire rst,
    input wire signed [7:0] signal,
    output reg zero_cross
);
    reg signed [7:0] prev_signal;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            zero_cross <= 0;
            prev_signal <= 0;
        end else begin
            zero_cross <= (prev_signal[7] != signal[7]) && (signal != 0);
            prev_signal <= signal;
        end
    end
endmodule

