module serializer (
    input clk,
    input rst,
    input start,
    input [15:0] data_in,
    output reg serial_out,
    output reg done
);
    reg [3:0] bit_count; // To count the bits serialized
    reg [15:0] shift_reg; // To hold the data to be serialized

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            serial_out <= 0;
            done <= 0;
            bit_count <= 0;
            shift_reg <= 0;
        end else if (start) begin
            shift_reg <= data_in;
            bit_count <= 0;
            done <= 0;
        end else if (bit_count < 16) begin
            serial_out <= shift_reg[15]; // Send the MSB first
            shift_reg <= {shift_reg[14:0], 1'b0}; // Shift left
            bit_count <= bit_count + 1;
            if (bit_count == 15) begin
                done <= 1; // Indicate serialization is done after last bit
            end else begin
                done <= 0;
            end
        end
    end
endmodule

