module pll (
    input wire clk_ref,          // Reference clock input
    input wire clk_in,           // Input clock
    input wire reset,           // Reset signal
    output reg clk_out          // Output clock
);
    reg [1:0] phase;            // Phase detector output
    reg vco;                    // Voltage-controlled oscillator output

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            phase <= 2'b00;
            vco <= 1'b0;
            clk_out <= 1'b0;
        end else begin
            // Simple phase detection
            if (clk_in) phase <= phase + 1;
            // Simple VCO behavior
            vco <= ~vco;
            // Output clock is half of VCO frequency
            clk_out <= vco;
        end
    end
endmodule

