module uart_transmitter (  
    input wire clk,  
    input wire start,  
    input wire [7:0] data,  
    output reg tx  
);  
    reg [3:0] bit_cnt;  
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit  
    reg sending;  

    always @(posedge clk) begin  
        if (start && !sending) begin  
            sending <= 1;  
            shift_reg <= {1'b1, data, 1'b0}; // 1 stop bit, 8 data bits, 1 start bit  
            bit_cnt <= 0;  
        end else if (sending) begin  
            tx <= shift_reg[bit_cnt];  
            bit_cnt <= bit_cnt + 1;  
            if (bit_cnt == 9) begin  
                sending <= 0;  
            end  
        end  
    end  
endmodule

