module divide_by_8(  
    input clk,  
    input reset,  
    output reg out  
);  
    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 3'b000;  
            out <= 0;  
        end else begin  
            count <= count + 1;  
            if (count == 3'b111)  
