module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire kick,  
    output reg timeout  
);  
    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            timeout <= 0;  
        end else if (kick) begin  
            count <= 0;  
            timeout <= 0;  
        end else begin  
            if (count < 5) begin  
                count <= count + 1;  
            end else begin  
                timeout <= 1;  
            end  
        end  
    end  
endmodule

