module deserializer (
    input wire clk,
    input wire rst,
    input wire [15:0] parallel_in,
    output reg serial_out
);
    reg [3:0] count; // 4 bits to count 0 to 15

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            serial_out <= 0;
        end else begin
            serial_out <= parallel_in[15 - count]; // output MSB first
            if (count < 15)
                count <= count + 1;
            else
                count <= 0; // reset count after 16 bits are output
        end
    end
endmodule

