module crc4 (
    input wire clk,
    input wire [3:0] data,
    output reg [3:0] crc
);
    reg [3:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {shift_reg[2:0], data[0]};
        if (shift_reg[3] ^ data[3]) begin
            shift_reg[3:0] <= {shift_reg[2:0], 1'b0} ^ 4'b10011; // Polynomial x^4 + x + 1
        end
    end

    always @(posedge clk) begin
        crc <= shift_reg;
    end
endmodule

