module AStarFSM (
    input wire clk,
    input wire rst,
    input wire [4:0] start_node,
    input wire [4:0] goal_node,
    output reg path_found
);
    parameter IDLE = 2'b00, INIT = 2'b01, EVAL = 2'b10, DONE = 2'b11;
    reg [1:0] state, next_state;

    always @(posedge clk or posedge rst) begin
        if (rst) 
            state <= IDLE;
        else 
            state <= next_state;
    end

    always @(*) begin
        case(state)
            IDLE: begin
                if (start_node != 0 && goal_node != 0) 
                    next_state = INIT;
                else 
                    next_state = IDLE;
            end
            INIT: begin
                next_state = EVAL;
            end
            EVAL: begin
                // Placeholder for evaluation logic
                // Assuming we find the path, move to DONE
                next_state = DONE;  
            end
            DONE: begin
                path_found = 1;
                next_state = IDLE; // Resetting for the next operation
            end
            default: next_state = IDLE;
        endcase
    end
endmodule

