module CarrierRecovery (
    input clk,             // System clock
    input reset,           // Reset signal
    input modulated_signal, // Input modulated signal
    output reg recovered_clk // Output recovered clock
);
    reg [3:0] counter;
    reg modulated_signal_d;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            recovered_clk <= 0;
        end else begin
            modulated_signal_d <= modulated_signal; // Delay signal for edge detection
            if (modulated_signal && !modulated_signal_d) begin
                counter <= counter + 1;
                if (counter == 4'b1111) begin
                    recovered_clk <= ~recovered_clk; // Toggle recovered clock
                    counter <= 0;
                end
            end
        end
    end
endmodule

