module aes_8bit (  
    input [7:0] data_in,  
    input [127:0] key,  
    input clk,  
    input start,  
    output reg [7:0] data_out,  
    output reg done  
);  

    reg [127:0] round_key;  
    reg [3:0] state;  

    always @(posedge clk) begin  
        if (start) begin  
            // Key schedule (simplified for brevity)  
            round_key <= key;  
            state <= 0;  
            done <= 0;  
        end else begin  
            case (state)  
                0: begin  
                    // AddRoundKey  
                    data_out <= data_in ^ round_key[7:0];  
                    state <= 1;  
                end  
                1: begin  
                    // Simplified substitute bytes  
                    data_out <= (data_out ^ 8'h5A);  
                    state <= 2;  
                end  
                2: begin  
                    // ShiftRows (not applicable for 1 byte)  
                    state <= 3;  
                end  
                3: begin  
                    // MixColumns (not applicable for 1 byte)  
                    done <= 1;  
                    state <= 0;  
                end  
            endcase  
        end  
    end  
endmodule

