module serializer (
    input clk,
    input reset,
    input [15:0] parallel_in,
    output reg serial_out,
    output reg done
);
    reg [3:0] bit_count; // 4 bits to count from 0 to 15

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 0;
            serial_out <= 0;
            done <= 0;
        end else if (bit_count < 16) begin
            serial_out <= parallel_in[15 - bit_count]; // Output the bits from MSB to LSB
            bit_count <= bit_count + 1;
            done <= (bit_count == 15); // Set done high when the last bit is sent
        end
    end
endmodule

