module divider_4bit (  
    input clk,  
    input rst,  
    input start,  
    input [3:0] numerator,  
    input [3:0] denominator,  
    output reg [3:0] quotient,  
    output reg [3:0] remainder,  
    output reg done  
);  
    reg [3:0] count;  
    reg [3:0] temp_numerator;  
    reg [3:0] temp_denominator;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            quotient <= 0;  
            remainder <= 0;  
            done <= 0;  
            count <= 0;  
        end else if (start) begin  
            temp_numerator <= numerator;  
            temp_denominator <= denominator;  
            quotient <= 0;  
            remainder <= 0;  
            count <= 4;  
            done <= 0;  
        end else if (count > 0) begin  
            if (temp_numerator >= temp_denominator) begin  
                temp_numerator <= temp_numerator - temp_denominator;  
                quotient <= quotient + 1;  
            end  
            count <= count - 1;  
        end else begin  
            remainder <= temp_numerator;  
            done <= 1;  
        end  
    end  
endmodule

