module fir_filter (
    input wire clk,
    input wire [15:0] x,  // 16-bit input sample
    output reg [15:0] y   // 16-bit output sample
);
    reg [15:0] coeffs [0:15]; // Coefficients for the FIR filter
    reg [31:0] accum;          // Accumulator for the output
    reg [15:0] shift_reg [0:15]; // Shift register for input samples

    integer i;

    initial begin
        // Define the coefficients (example values)
        coeffs[0] = 16'h0001;
        coeffs[1] = 16'h0002;
        coeffs[2] = 16'h0003;
        coeffs[3] = 16'h0004;
        coeffs[4] = 16'h0005;
        coeffs[5] = 16'h0006;
        coeffs[6] = 16'h0007;
        coeffs[7] = 16'h0008;
        coeffs[8] = 16'h0009;
        coeffs[9] = 16'h000A;
        coeffs[10] = 16'h000B;
        coeffs[11] = 16'h000C;
        coeffs[12] = 16'h000D;
        coeffs[13] = 16'h000E;
        coeffs[14] = 16'h000F;
        coeffs[15] = 16'h0010;
    end

    always @(posedge clk) begin
        // Shift the input samples into the shift register
        for (i = 15; i > 0; i = i - 1) begin
            shift_reg[i] <= shift_reg[i - 1];
        end
        shift_reg[0] <= x;

        // Perform the FIR calculation
        accum = 32'h0;
        for (i = 0; i < 16; i = i + 1) begin
            accum = accum + (shift_reg[i] * coeffs[i]);
        end

        y <= accum[15:0]; // Take the lower 16 bits as the output
    end
endmodule

