module crystal_oscillator (
    input clk,
    input reset,
    input [3:0] freq_div,
    output reg out
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            out <= 0;
        end else begin
            if (counter == (1 << freq_div) - 1) begin
                out <= ~out;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

