module watchdog_timer(
    input wire clk,
    input wire reset,
    input wire [3:0] timeout,
    output reg watchdog_expired
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            watchdog_expired <= 1'b0;
        end else begin
            if (counter < timeout) begin
                counter <= counter + 1;
                watchdog_expired <= 1'b0;
            end else begin
                watchdog_expired <= 1'b1;
            end
        end
    end
endmodule

