module SR_latch_with_enable (  
    input wire S,  
    input wire R,  
    input wire E,  
    output reg Q  
);  
    always @(posedge E) begin  
        if (S && R)  
            Q <= Q; // Indeterminate state, retains last value  
        else if (S)  
            Q <= 1; // Set  
        else if (R)  
            Q <= 0; // Reset  
    end  
endmodule

