module temp_sensor_controller(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] temperature,  
    output reg alarm  
);  
    parameter THRESHOLD = 8'd100;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            alarm <= 1'b0;  
        end else begin  
            if (temperature > THRESHOLD) begin  
                alarm <= 1'b1;  
            end else begin  
                alarm <= 1'b0;  
            end  
        end  
    end  
endmodule

