        .CLK(CLK),
        .RE(RE),
        .WE(WE),
        .data(data),
        .out(out)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            RE = 0;
            WE = 0;
            data = 4'b0;
            @(posedge CLK);
            #1;
        end
        endtask
    task testcase001;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Write 4'hA and Read", test_num);


            WE = 1;
            data = 4'hA;
            @(posedge CLK);
            #1;
            WE = 0;


            RE = 1;
            #1;
            #1;

            check_outputs(4'hA);
        end
        endtask

    task testcase002;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Attempt write with WE=0", test_num);


            WE = 1;
            data = 4'h5;
            @(posedge CLK);
            #1;


            WE = 0;
            data = 4'hC;
            @(posedge CLK);
            #1;


            RE = 1;
            #1;
            #1;

            check_outputs(4'h5);
        end
        endtask

    task testcase003;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Data persistence check", test_num);


            WE = 1;
            data = 4'hF;
            @(posedge CLK);
            #1;
            WE = 0;


            repeat(3) @(posedge CLK);
            #1;


            RE = 1;
            #1;
            #1;

