module rc_oscillator (
    input clk,
    input rst,
    input [7:0] R, // Resistance value
    input [7:0] C, // Capacitance value
    output reg out // Square wave output
);

parameter MAX_COUNT = 8'd255; // Maximum count value
reg [7:0] count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        count <= 8'd0;
        out <= 1'b0;
    end else begin
        if (count < (R * C)) begin
            count <= count + 1;
        end else begin
            count <= 8'd0;
            out <= ~out; // Toggle the output
        end
    end
end
endmodule

